use std::json
use std::fs

struct Item {
    sku: string,
    qty: int,
    price: float,
}

struct Order {
    id: int,
    customer: string,
    items: Vec<Item>,
    note: Option<string>,
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let r = json.parse_string::<Vec<Order>>(text)
    match r {
        Ok(orders) => {
            let mut names: Vec<string> = []
            for o in orders {
                if !names.contains(o.customer) {
                    names.push(o.customer)
                }
            }
            names.sort()
            for n in names {
                let mut total = 0.0
                for o in orders {
                    if o.customer == n {
                        for it in o.items {
                            total += (it.qty as float) * it.price
                        }
                    }
                }
                println("${n} ${total:.2}")
            }
        }
        Err(e) => {
            println("invalid input")
            std::process::exit(1)
        }
    }
}

